package com.slss.service;
import com.slss.domain.*; import com.slss.repository.*; import jakarta.transaction.Transactional; import org.springframework.stereotype.Service; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.http.HttpStatus; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@Service public class ProductionBatchService { final ProductionBatchRepository batches; final AssetRepository assets; final LifecycleEventRepository lifecycle; final TenantScopeService tenantScope; public ProductionBatchService(ProductionBatchRepository b,AssetRepository a,LifecycleEventRepository l,TenantScopeService ts){this.batches=b;this.assets=a;this.lifecycle=l;this.tenantScope=ts;}
 @Transactional public ProductionBatch create(String name){if(batches.findByBatchName(name).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"批次已存在");var b=new ProductionBatch();b.setBatchName(name);b.setTenant(tenantScope.tenantForCreate(name));return batches.save(b);}
 @Transactional public Asset saveDraftRow(Long id, Asset incoming){var b=batches.findById(id).orElseThrow();if(!"DRAFT".equals(b.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"批次已提交");var sn=Optional.ofNullable(incoming.getMachineSn()).orElse("").trim();if(sn.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"机器 SN 不能为空");var global=assets.findByMachineSnIgnoreCase(sn);if(global.isPresent()&&(global.get().getBatch()==null||!global.get().getBatch().getId().equals(id)))throw new ResponseStatusException(HttpStatus.CONFLICT,"整机 SN "+sn+" 已绑定设备 "+global.get().getMachineSn()+"，不能重复使用");var a=assets.findByBatch_IdAndMachineSnIgnoreCase(id,sn).orElseGet(()->{var x=new Asset();x.setBatch(b);b.getAssets().add(x);return x;});a.setMachineSn(sn);a.setModel(incoming.getModel());a.setContractNo(incoming.getContractNo());a.setInvoiceDate(incoming.getInvoiceDate());return assets.save(a);}
 @Transactional public ProductionBatch commit(Long id,List<Asset> rows){var b=batches.findById(id).orElseThrow();if(rows==null||rows.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"批次至少需要一条资产");if(!"DRAFT".equals(b.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"批次不可重复提交");var seen=new HashSet<String>();var existing=assets.findAll().stream().map(x->x.getMachineSn().toLowerCase(Locale.ROOT)).collect(java.util.stream.Collectors.toSet());for(var a:rows){var sn=a.getMachineSn()==null?"":a.getMachineSn().trim();if(sn.isBlank()||!seen.add(sn.toLowerCase(Locale.ROOT))||existing.contains(sn.toLowerCase(Locale.ROOT)))throw new ResponseStatusException(HttpStatus.CONFLICT,"存在重复或已入库的机器 SN: "+sn);a.setMachineSn(sn);a.setBatch(b);b.getAssets().add(a);}b.setStatus("COMMITTED");var saved=batches.save(b);if(lifecycle!=null)for(var a:saved.getAssets()){var e=new LifecycleEvent();e.setAsset(a);e.setEventType("PRODUCTION_REGISTERED");e.setDetails("生产批次 "+saved.getBatchName()+" 提交入库");lifecycle.save(e);}return saved;}
}
